import React from "react";
import { Button } from "antd";

import { UserTopNav } from ".";
import AppLogo from "../media/logo.png";
import { AppIcon } from "./SVGFiles";

interface Props {
    title: string;
    onMenuClick: () => void;
}

export const AppHeader: React.FC<Props> = ({ title, onMenuClick }) => {
    return (
        <header className="ss-app-config-main-header">
            <div>
                <h1>
                    <Button
                        className="menu-burger"
                        type="link"
                        shape="circle"
                        icon={<AppIcon asset="burger-menu" />}
                        onClick={() => onMenuClick()}
                    />
                    <span>
                        <img src={AppLogo} alt="Affinity - making work life easy" height={48} />
                        {window.location.href.includes("testaffinitylogon") && <span>TE</span>}
                    </span>
                </h1>
                <div>
                    <UserTopNav />
                </div>
            </div>
        </header>
    );
};
